	ETH1AddressWithdrawalPrefixByte: byte(1),
	CompoundingWithdrawalPrefixByte: byte(2),
	ZeroHash:                        [32]byte{},

	// Time parameter constants.
	MinAttestationInclusionDelay:     1,
